-- Lessons generated by supabase/lessons/build.mjs — edit the .mjs sources, not this file.

-- Lesson 1: Глагол to be (13 sections, 206 items)
insert into public.lessons (slug, title, subtitle, position, content)
values ('to-be', 'Глагол to be', 'am / is / are, отрицания, вопросы, порядок слов, страны, its / interested, перевод, was / were, знакомство, фразы с доски', 1, $lesson${"sections":[{"id":"plus","nav":"am / is / are","eyebrow":"Тема 1 · утверждение","title":"Глагол to be: am, is, are","theory":"<p>По-русски мы говорим «Я врач», «Она дома», «Суп горячий» — без глагола. В английском так нельзя: между «кто» и «кто такой / какой / где» всегда стоит глагол <b>to be</b> — «быть, являться, находиться».</p>\n<div class=\"formula\"><span class=\"slot\">кто / что</span><span class=\"plus\">+</span><span class=\"slot be\">am · is · are</span><span class=\"plus\">+</span><span class=\"slot\">кто такой · какой · где · откуда</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Кто</th><th>Полная форма</th><th>Коротко</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>I</td><td>I <mark>am</mark></td><td>I'm</td><td>I'm a designer.</td></tr>\n<tr><td>he / she / it</td><td>she <mark>is</mark></td><td>he's · she's · it's</td><td>She's at work.</td></tr>\n<tr><td>we / you / they</td><td>they <mark>are</mark></td><td>we're · you're · they're</td><td>They're from Oslo.</td></tr>\n</tbody></table></div>\n<p><b>Как выбрать форму.</b> Один человек или предмет — <b>is</b>. Несколько — <b>are</b>. <b>I</b> — только <b>am</b>. <b>You</b> — это и «ты», и «вы», поэтому всегда <b>are</b>.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>Кто в предложении</th><th>Заменяем на</th><th>Форма</th></tr></thead>\n<tbody>\n<tr><td>Anna</td><td>she</td><td><mark>is</mark></td></tr>\n<tr><td>Anna and Max</td><td>they</td><td><mark>are</mark></td></tr>\n<tr><td>my phone</td><td>it</td><td><mark>is</mark></td></tr>\n<tr><td>my shoes</td><td>they</td><td><mark>are</mark></td></tr>\n</tbody></table></div>\n<h3>Разбор примеров</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Моя мама — учитель.</span><span class=\"en\">My mum <mark>is</mark> a teacher.</span><span class=\"why\">мама = she → is</span></li>\n<li><span class=\"ru\">Мы в кафе.</span><span class=\"en\">We <mark>are</mark> in a café.</span><span class=\"why\">где находимся — тоже через to be</span></li>\n<li><span class=\"ru\">Мне 22 года.</span><span class=\"en\">I <mark>am</mark> 22.</span><span class=\"why\">возраст — через to be, а не через have</span></li>\n<li><span class=\"ru\">На улице холодно.</span><span class=\"en\">It <mark>is</mark> cold outside.</span><span class=\"why\">подлежащее обязательно, поэтому it</span></li>\n</ul>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span><b>to be</b> — быть, <b>to work</b> — работать. Не смешивайте их: <span class=\"yes\">I work from home ✔</span> <span class=\"no\">I am work from home</span></span></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span><b>It is cold.</b> В английском предложении всегда есть «кто / что». Не <span class=\"no\">Is cold</span>, а <span class=\"yes\">It is cold ✔</span></span></div>","groups":[{"title":"Выберите am, is или are","items":[{"t":"choice","q":"My sister ___ a nurse.","o":["am","is","are"],"a":"is","ex":"My sister = she → is."},{"t":"choice","q":"I ___ at the airport now.","o":["am","is","are"],"a":"am","ex":"С I всегда am."},{"t":"choice","q":"Oliver and Mia ___ from Canada.","o":["am","is","are"],"a":"are","ex":"Два человека = they → are."},{"t":"choice","q":"The soup ___ very hot.","o":["am","is","are"],"a":"is","ex":"Суп — один предмет = it → is."},{"t":"choice","q":"You ___ right!","o":["am","is","are"],"a":"are","ex":"С you всегда are, даже если это один человек."},{"t":"choice","q":"My keys ___ on the table.","o":["am","is","are"],"a":"are","ex":"Ключи — их несколько = they → are."},{"t":"choice","q":"It ___ Friday today.","o":["am","is","are"],"a":"is","ex":"It → is."},{"t":"choice","q":"We ___ ready.","o":["am","is","are"],"a":"are","ex":"We → are."}]},{"title":"Впишите am, is или are","items":[{"t":"input","q":"Mr Brown ___ our new teacher.","a":["is"],"ex":"Mr Brown = he → is."},{"t":"input","q":"The children ___ in the garden.","a":["are"],"ex":"Children — «дети», множественное число → are."},{"t":"input","q":"I ___ 19 years old.","a":["am"],"ex":"I → am. Возраст — через to be."},{"t":"input","q":"This film ___ really boring.","a":["is"],"ex":"Фильм — один = it → is."}]},{"title":"Какое предложение правильное?","items":[{"t":"choice","q":"«Сегодня холодно.»","o":["Is cold today.","It is cold today.","It cold today."],"a":"It is cold today.","ex":"Нужны и подлежащее it, и глагол is.","b":{"Is cold today.":"Пропущено подлежащее. В английском «кто / что» есть всегда, здесь это it.","It cold today.":"Пропущен глагол is. Без to be нельзя."}},{"t":"choice","q":"«Я работаю в банке.»","o":["I am work in a bank.","I work in a bank.","I working in a bank."],"a":"I work in a bank.","ex":"Уже есть глагол-действие work, поэтому am не нужен.","b":{"I am work in a bank.":"work — уже сказуемое. am рядом с ним лишний.","I working in a bank.":"Форма -ing без am не бывает. И по смыслу нужно просто I work."}},{"t":"choice","q":"«Ему 40 лет.»","o":["He has 40 years.","He is 40.","He 40 years."],"a":"He is 40.","ex":"Возраст — через to be: He is 40 (или He is 40 years old).","b":{"He has 40 years.":"Дословный перевод. Возраст по-английски — через to be: «он есть 40».","He 40 years.":"Пропущен глагол is."}}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"She are from Portugal.","w":1,"c":"is","ex":"She → is."},{"t":"fix","q":"I is very hungry.","w":1,"c":"am","ex":"I → только am."},{"t":"fix","q":"My friends is at the cinema.","w":2,"c":"are","ex":"Friends — несколько человек → are."},{"t":"fix","q":"The weather are perfect today.","w":2,"c":"is","ex":"Weather — одно слово в единственном числе → is. Как на стикере: The weather is perfect."}]}]},{"id":"neg","nav":"Отрицание","eyebrow":"Тема 2 · отрицание","title":"«Не»: am not, isn't, aren't","theory":"<p>Чтобы сказать «не», ставим <b>not</b> сразу после am / is / are. Больше ничего в предложении не меняется.</p>\n<div class=\"formula\"><span class=\"slot\">кто / что</span><span class=\"plus\">+</span><span class=\"slot be\">am · is · are</span><span class=\"plus\">+</span><span class=\"slot be\">not</span><span class=\"plus\">+</span><span class=\"slot\">остальное</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Кто</th><th>Полная форма</th><th>Коротко</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>I</td><td>I am not</td><td><mark>I'm not</mark></td><td>I'm not tired.</td></tr>\n<tr><td>he / she / it</td><td>it is not</td><td><mark>isn't</mark> · it's not</td><td>It isn't expensive.</td></tr>\n<tr><td>we / you / they</td><td>they are not</td><td><mark>aren't</mark> · they're not</td><td>They aren't at home.</td></tr>\n</tbody></table></div>\n<h3>Разбор примеров</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я не голоден.</span><span class=\"en\">I<mark>'m not</mark> hungry.</span></li>\n<li><span class=\"ru\">Это не мой зонт.</span><span class=\"en\">This <mark>isn't</mark> my umbrella.</span><span class=\"why\">this = it → is → isn't</span></li>\n<li><span class=\"ru\">Моих друзей здесь нет.</span><span class=\"en\">My friends <mark>aren't</mark> here.</span><span class=\"why\">friends = they → are → aren't</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Формы «amn't» не существует: <span class=\"no\">I amn't</span> <span class=\"yes\">I'm not ✔</span></span><span>Not стоит после to be, а не перед ним: <span class=\"no\">She not is</span> <span class=\"yes\">She isn't ✔</span></span></div>","groups":[{"title":"Выберите правильную форму","items":[{"t":"choice","q":"Tom ___ at home.","o":["am not","isn't","aren't"],"a":"isn't","ex":"Tom = he → is not → isn't."},{"t":"choice","q":"I ___ a student.","o":["am not","isn't","aren't"],"a":"am not","ex":"I → am not (коротко I'm not)."},{"t":"choice","q":"These shoes ___ cheap.","o":["am not","isn't","aren't"],"a":"aren't","ex":"Shoes — их несколько → aren't."},{"t":"choice","q":"The museum ___ open on Mondays.","o":["am not","isn't","aren't"],"a":"isn't","ex":"Museum = it → isn't."},{"t":"choice","q":"We ___ late, the train is at 9.","o":["am not","isn't","aren't"],"a":"aren't","ex":"We → aren't."}]},{"title":"Сделайте предложение отрицательным","items":[{"t":"input","q":"It is my phone.","a":["It isn't my phone."],"ex":"It is → It isn't. Правильно и It's not, и It is not."},{"t":"input","q":"I'm from Poland.","a":["I'm not from Poland."],"ex":"I'm → I'm not."},{"t":"input","q":"They are brothers.","a":["They aren't brothers."],"ex":"They are → They aren't."},{"t":"input","q":"The bus is full.","a":["The bus isn't full."],"ex":"Is → isn't."},{"t":"input","q":"You're in the wrong room.","a":["You aren't in the wrong room."],"ex":"You're → You aren't (или You're not)."}]},{"title":"Составьте предложение: (+) — утверждение, (−) — отрицание","items":[{"t":"input","q":"my flat / big (−)","a":["My flat isn't big."],"ex":"My flat = it → isn't."},{"t":"input","q":"Anna and Leo / 20 years old (+)","a":["Anna and Leo are 20 years old.","Anna and Leo are 20.","Anna and Leo are twenty years old.","Anna and Leo are twenty."],"ex":"Двое → are."},{"t":"input","q":"I / tired (−)","a":["I'm not tired."],"ex":"I → I'm not."},{"t":"input","q":"the weather / nice today (+)","a":["The weather is nice today."],"ex":"Weather → is."},{"t":"input","q":"your coffee / cold (−)","a":["Your coffee isn't cold."],"ex":"Coffee = it → isn't."}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"I amn't hungry.","w":1,"c":"am not","ex":"Формы amn't нет: I am not / I'm not."},{"t":"fix","q":"The shops isn't open.","w":2,"c":"aren't","ex":"Shops — несколько → aren't."},{"t":"fix","q":"He aren't my brother.","w":1,"c":"isn't","ex":"He → isn't."}]}]},{"id":"yn","nav":"Вопросы да / нет","eyebrow":"Тема 3 · вопрос","title":"Вопросы «да / нет» и короткие ответы","theory":"<p>Чтобы задать вопрос, на который отвечают «да» или «нет», <b>меняем местами</b> подлежащее и am / is / are. По-русски вопрос задают одной интонацией, в английском нужен именно другой порядок слов.</p>\n<div class=\"formula\"><span class=\"slot be\">Am · Is · Are</span><span class=\"plus\">+</span><span class=\"slot\">кто / что</span><span class=\"plus\">+</span><span class=\"slot\">остальное</span><span class=\"plus\">?</span></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">утверждение → вопрос</span><span class=\"en\">You <mark>are</mark> tired. → <mark>Are</mark> you tired?</span></li>\n<li><span class=\"ru\">утверждение → вопрос</span><span class=\"en\">The shop <mark>is</mark> open. → <mark>Is</mark> the shop open?</span></li>\n</ul>\n<div class=\"tbl\"><table>\n<thead><tr><th>Вопрос</th><th>Да</th><th>Нет</th></tr></thead>\n<tbody>\n<tr><td>Am I late?</td><td>Yes, you are.</td><td>No, you aren't.</td></tr>\n<tr><td>Is she at work?</td><td>Yes, she is.</td><td>No, she isn't.</td></tr>\n<tr><td>Is it new?</td><td>Yes, it is.</td><td>No, it isn't.</td></tr>\n<tr><td>Are you ready?</td><td>Yes, I am.</td><td>No, I'm not.</td></tr>\n<tr><td>Are they here?</td><td>Yes, they are.</td><td>No, they aren't.</td></tr>\n</tbody></table></div>\n<p><b>В ответе имя меняем на местоимение:</b> Is Tom here? — Yes, <b>he</b> is. <b>Спросили «ты?» — отвечаем «я»:</b> Are you OK? — Yes, <b>I</b> am.</p>\n<h3>Разбор примеров</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Ты занят? — Да.</span><span class=\"en\"><mark>Are</mark> you busy? — Yes, I am.</span></li>\n<li><span class=\"ru\">Магазин открыт? — Нет.</span><span class=\"en\"><mark>Is</mark> the shop open? — No, it isn't.</span></li>\n<li><span class=\"ru\">Твои родители дома? — Да.</span><span class=\"en\"><mark>Are</mark> your parents at home? — Yes, they are.</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>В коротком «да» не сокращаем: <span class=\"no\">Yes, I'm</span> <span class=\"yes\">Yes, I am ✔</span> В «нет» сокращать можно: <span class=\"yes\">No, I'm not ✔</span></span></div>","groups":[{"title":"Выберите Am, Is или Are","items":[{"t":"choice","q":"___ your brother married?","o":["Am","Is","Are"],"a":"Is","ex":"Your brother = he → Is."},{"t":"choice","q":"___ you cold?","o":["Am","Is","Are"],"a":"Are","ex":"You → Are."},{"t":"choice","q":"___ I late?","o":["Am","Is","Are"],"a":"Am","ex":"I → Am."},{"t":"choice","q":"___ the shops open today?","o":["Am","Is","Are"],"a":"Are","ex":"Shops — несколько → Are."},{"t":"choice","q":"___ this seat free?","o":["Am","Is","Are"],"a":"Is","ex":"This seat = it → Is."}]},{"title":"Превратите в вопрос","items":[{"t":"input","q":"She is a designer.","a":["Is she a designer?"],"ex":"Меняем местами she и is."},{"t":"input","q":"They are at the hotel.","a":["Are they at the hotel?"],"ex":"Меняем местами they и are."},{"t":"input","q":"Your car is new.","a":["Is your car new?"],"ex":"Подлежащее здесь из двух слов — your car. Is встаёт перед ним целиком."},{"t":"input","q":"It is far from here.","a":["Is it far from here?"],"ex":"It is → Is it."},{"t":"input","q":"The children are asleep.","a":["Are the children asleep?"],"ex":"The children are → Are the children."}]},{"title":"Выберите короткий ответ","items":[{"t":"choice","q":"Are you from Georgia? — No, ___.","o":["I'm not","I amn't","I don't"],"a":"I'm not","ex":"Are you…? → No, I'm not.","b":{"I amn't":"Формы amn't не существует.","I don't":"Вопрос задан с are, значит и ответ с to be, а не с don't."}},{"t":"choice","q":"Is Maria your cousin? — Yes, ___.","o":["she is","she's","Maria is"],"a":"she is","ex":"Имя → местоимение, и в «да» без сокращения.","b":{"she's":"В коротком «да» сокращение в конце нельзя.","Maria is":"В коротком ответе имя меняем на местоимение."}},{"t":"choice","q":"Are the tickets expensive? — No, ___.","o":["they aren't","it isn't","they not"],"a":"they aren't","ex":"Tickets → they → they aren't.","b":{"it isn't":"Tickets — несколько, значит they.","they not":"Пропущен глагол: нужно they aren't."}},{"t":"choice","q":"Is it your bag? — Yes, ___.","o":["it is","it's","is it"],"a":"it is","ex":"Yes, it is. Сокращение it's в конце ответа нельзя.","b":{"it's":"В коротком «да» сокращение в конце нельзя.","is it":"Это порядок вопроса. В ответе сначала подлежащее: it is."}},{"t":"choice","q":"Are you and Sam friends? — Yes, ___.","o":["we are","you are","they are"],"a":"we are","ex":"«Ты и Сэм» — отвечающий говорит про себя и Сэма → we.","b":{"you are":"Спросили про «тебя и Сэма». Отвечающий говорит про себя, значит «мы».","they are":"Отвечающий сам входит в эту пару, значит «мы», а не «они»."}}]}]},{"id":"wh","nav":"Вопросы со словами","eyebrow":"Тема 4 · вопрос","title":"Вопросы с where, what, when, who, how","theory":"<p>Если нужен не ответ «да / нет», а информация (где, когда, кто), ставим <b>вопросительное слово в начало</b>. Дальше порядок такой же, как в вопросе «да / нет».</p>\n<div class=\"formula\"><span class=\"slot\">вопр. слово</span><span class=\"plus\">+</span><span class=\"slot be\">am · is · are</span><span class=\"plus\">+</span><span class=\"slot\">кто / что</span><span class=\"plus\">+</span><span class=\"slot\">остальное</span><span class=\"plus\">?</span></div>\n<div class=\"compare\">\n<div><span class=\"tag\">да / нет</span><p class=\"en\">Are you at home?</p><p class=\"ru\">Ты дома? — Yes, I am.</p></div>\n<div><span class=\"tag\">нужна информация</span><p class=\"en\">When are you at home?</p><p class=\"ru\">Когда ты дома? — After 7.</p></div>\n</div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Слово</th><th>Значение</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>What</td><td>что, какой</td><td>What is your name?</td></tr>\n<tr><td>Where</td><td>где</td><td>Where is the station?</td></tr>\n<tr><td>Where … from</td><td>откуда</td><td>Where are you from?</td></tr>\n<tr><td>When</td><td>когда</td><td>When is your birthday?</td></tr>\n<tr><td>What time</td><td>во сколько</td><td>What time is the lesson?</td></tr>\n<tr><td>Who</td><td>кто</td><td>Who is your teacher?</td></tr>\n<tr><td>How</td><td>как</td><td>How are you?</td></tr>\n<tr><td>How old</td><td>сколько лет</td><td>How old is your son?</td></tr>\n<tr><td>Why</td><td>почему</td><td>Why are you sad?</td></tr>\n</tbody></table></div>\n<p>С <b>is</b> можно сокращать: What's, Where's, Who's, How's. С <b>are</b> так не делаем.</p>\n<h3>Разбор примеров</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Откуда твой начальник?</span><span class=\"en\">Where <mark>is</mark> your boss from?</span><span class=\"why\">boss = he → is; from уходит в конец</span></li>\n<li><span class=\"ru\">Во сколько фильм?</span><span class=\"en\">What time <mark>is</mark> the film?</span></li>\n<li><span class=\"ru\">Кто эти люди?</span><span class=\"en\">Who <mark>are</mark> these people?</span><span class=\"why\">people — несколько → are</span></li>\n</ul>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>1) <b>Are</b> you at home? &nbsp;2) <i>When</i> <b>are</b> you at home? Порядок после вопросительного слова тот же.</span></div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>Предлог уходит в конец вопроса: <span class=\"yes\">Where are you from? ✔</span> <span class=\"yes\">What are you interested in? ✔</span></span><span>Порядок не как в утверждении: <span class=\"no\">Where you are?</span> <span class=\"yes\">Where are you? ✔</span></span></div>","groups":[{"title":"Выберите вопросительное слово","items":[{"t":"choice","q":"___ is your favourite singer? — Adele.","o":["Who","Where","When"],"a":"Who","ex":"Спрашиваем про человека → Who.","b":{"Where":"Where — «где». А в ответе человек.","When":"When — «когда». А в ответе человек."}},{"t":"choice","q":"___ is the meeting? — On Friday.","o":["When","Where","Who"],"a":"When","ex":"Ответ — день → When.","b":{"Where":"Where — «где». А в ответе день.","Who":"Who — «кто». А в ответе день."}},{"t":"choice","q":"___ are my glasses? — On your head!","o":["Where","What","How"],"a":"Where","ex":"Ответ — место → Where.","b":{"What":"What — «что». А в ответе место.","How":"How — «как». А в ответе место."}},{"t":"choice","q":"___ is your grandmother? — She's 82.","o":["How old","How","What"],"a":"How old","ex":"Ответ — возраст → How old.","b":{"How":"How is your grandmother? — «Как бабушка?» Ответ был бы «She's fine». В ответе возраст.","What":"What — «что». А в ответе возраст."}},{"t":"choice","q":"___ is your new job? — It's great, thanks.","o":["How","What","Who"],"a":"How","ex":"«Как тебе новая работа?» → How.","b":{"What":"What is your new job? — «Кем ты работаешь?» А в ответе впечатление.","Who":"Who — «кто». А в ответе впечатление."}},{"t":"choice","q":"___ is the concert? — At 7:30.","o":["What time","Where","Who"],"a":"What time","ex":"Ответ — время → What time.","b":{"Where":"Where — «где». А в ответе время.","Who":"Who — «кто». А в ответе время."}},{"t":"choice","q":"___ is your email address? — kira@mail.com","o":["What","Who","How"],"a":"What","ex":"«Какой у тебя адрес?» → What.","b":{"Who":"Who — «кто». Адрес — это «что».","How":"How — «как». Спрашиваем, какой адрес."}},{"t":"choice","q":"___ are you tired? — Because I work a lot.","o":["Why","When","Where"],"a":"Why","ex":"Ответ начинается с because → Why.","b":{"When":"When — «когда». Ответ с because — это причина.","Where":"Where — «где». Ответ с because — это причина."}}]},{"title":"Соберите вопрос из слов","items":[{"t":"order","w":["from","your","where","are","parents"],"a":["Where are your parents from?"],"ex":"Where + are + your parents + from?"},{"t":"order","w":["your","what","is","surname"],"a":["What is your surname?"],"ex":"What + is + your surname?"},{"t":"order","w":["the","when","exam","is"],"a":["When is the exam?"],"ex":"When + is + the exam?"},{"t":"order","w":["you","interested","what","are","in"],"a":["What are you interested in?"],"ex":"Предлог in уходит в конец."},{"t":"order","w":["is","manager","who","the"],"a":["Who is the manager?"],"ex":"Who + is + the manager?"}]},{"title":"Задайте вопрос, на который это ответ","items":[{"t":"input","q":"My sister is in London.","p":"Спросите: где?","a":["Where is your sister?"],"ex":"Спрашиваем собеседника про его сестру: my → your."},{"t":"input","q":"The party is on Saturday.","p":"Спросите: когда?","a":["When is the party?"],"ex":"When + is + the party?"},{"t":"input","q":"I'm 27.","p":"Спросите: сколько лет?","a":["How old are you?"],"ex":"Ответ «I'm…» → вопрос «are you»."},{"t":"input","q":"Our teacher is Mr Lee.","p":"Спросите: кто?","a":["Who is your teacher?"],"ex":"Our → your."},{"t":"input","q":"My favourite colour is green.","p":"Спросите: какой?","a":["What is your favourite colour?","What is your favorite color?"],"ex":"What + is + your favourite colour?"}]},{"title":"Выберите правильный перевод","items":[{"t":"choice","q":"«Когда ты дома?»","o":["When are you at home?","When you are at home?","Are you when at home?"],"a":"When are you at home?","ex":"Вопросительное слово → are → you.","b":{"When you are at home?":"После вопросительного слова сначала are, потом you.","Are you when at home?":"Вопросительное слово всегда стоит в начале."}},{"t":"choice","q":"«Где твой офис?»","o":["Where is your office?","Where your office is?","Where is office your?"],"a":"Where is your office?","ex":"Where + is + your office.","b":{"Where your office is?":"После Where сначала is, потом подлежащее.","Where is office your?":"your стоит перед словом: your office."}}]}]},{"id":"order","nav":"Порядок слов","eyebrow":"Тема 5 · порядок слов","title":"Порядок слов в предложении","theory":"<p>По-русски слова можно переставлять: «По субботам в парке играет мой брат». В английском порядок жёсткий, как вагоны у поезда: переставить их нельзя.</p>\n<div class=\"formula\"><span class=\"slot\">кто / что</span><span class=\"plus\">+</span><span class=\"slot be\">что делает</span><span class=\"plus\">+</span><span class=\"slot\">кого / что</span><span class=\"plus\">+</span><span class=\"slot\">где</span><span class=\"plus\">+</span><span class=\"slot\">когда</span></div>\n<div class=\"tbl\"><table>\n<thead><tr><th>Кто</th><th>Что делает</th><th>Кого / что</th><th>Где</th><th>Когда</th></tr></thead>\n<tbody>\n<tr><td>I</td><td><mark>work</mark></td><td>—</td><td>from home</td><td>—</td></tr>\n<tr><td>My brother</td><td><mark>plays</mark></td><td>football</td><td>in the park</td><td>on Saturdays</td></tr>\n<tr><td>We</td><td><mark>are</mark></td><td>—</td><td>at the office</td><td>now</td></tr>\n</tbody></table></div>\n<p><b>«Кто / что» есть всегда.</b> Если по-русски его нет, ставим <b>it</b>: It's cold. It's 5 o'clock. It's Monday.</p>\n<p><b>Сказуемое одно.</b> Это либо обычный глагол-действие (work, live, like, play), либо am / is / are, если действия нет. Вместе их не ставим: <span class=\"yes\">I live in Kazan ✔</span> <span class=\"no\">I am live in Kazan</span></p>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>подлежащее + сказуемое + всё остальное.<br>кто/что? + что делает? + где + когда / зачем.<br><b>I work from home.</b></span></div>","groups":[{"title":"Соберите предложение","items":[{"t":"order","w":["work","I","home","from"],"a":["I work from home."],"ex":"I + work + from home."},{"t":"order","w":["in","every","swim","we","the","morning","pool"],"a":["We swim in the pool every morning."],"ex":"Кто + что делает + где + когда."},{"t":"order","w":["at","my","the","office","is","boss"],"a":["My boss is at the office."],"ex":"My boss + is + at the office."},{"t":"order","w":["cold","it","today","is"],"a":["It is cold today."],"ex":"It + is + cold + today."},{"t":"order","w":["live","a","they","in","flat","small"],"a":["They live in a small flat."],"ex":"They + live + in a small flat."},{"t":"order","w":["Sundays","cook","on","I","dinner"],"a":["I cook dinner on Sundays."],"ex":"Кто + что делает + что + когда."}]},{"title":"Нужен ли am / is / are? «—» значит «ничего не нужно»","items":[{"t":"choice","q":"I ___ live near the park.","o":["—","am","is"],"a":"—","ex":"Есть глагол live, поэтому am не нужен."},{"t":"choice","q":"She ___ happy today.","o":["—","is","are"],"a":"is","ex":"Действия нет, happy — «какая» → is."},{"t":"choice","q":"We ___ play tennis on Fridays.","o":["—","are","is"],"a":"—","ex":"Есть глагол play."},{"t":"choice","q":"My parents ___ doctors.","o":["—","is","are"],"a":"are","ex":"Действия нет, «кто такие» → are."},{"t":"choice","q":"They ___ like spicy food.","o":["—","are","is"],"a":"—","ex":"Есть глагол like."},{"t":"choice","q":"The book ___ on the shelf.","o":["—","is","are"],"a":"is","ex":"«Где находится» → is."}]},{"title":"Какое предложение правильное?","items":[{"t":"choice","q":"«Идёт дождь.»","o":["Is raining.","It is raining.","Raining it is."],"a":"It is raining.","ex":"Подлежащее it обязательно.","b":{"Is raining.":"Пропущено подлежащее it.","Raining it is.":"Порядок неверный: кто + is + остальное."}},{"t":"choice","q":"«Сейчас 8 часов.»","o":["Is 8 o'clock.","It is 8 o'clock.","8 o'clock is."],"a":"It is 8 o'clock.","ex":"Время — через It is.","b":{"Is 8 o'clock.":"Пропущено подлежащее it.","8 o'clock is.":"Порядок неверный: It + is + время."}},{"t":"choice","q":"«Мы ужинаем дома по пятницам.»","o":["We have dinner at home on Fridays.","We at home have dinner on Fridays.","On Fridays at home we dinner have."],"a":"We have dinner at home on Fridays.","ex":"Кто + что делает + что + где + когда.","b":{"We at home have dinner on Fridays.":"«Где» стоит после действия, а не перед ним.","On Fridays at home we dinner have.":"Это русский порядок слов. Нужно: кто + что делает + что + где + когда."}}]}]},{"id":"nat","nav":"Страны","eyebrow":"Тема 6 · лексика","title":"Страны и национальности","theory":"<p><b>Country</b> — страна, <b>nationality</b> — национальность. И то, и другое пишется <b>с большой буквы</b>.</p>\n<div class=\"formula\"><span class=\"slot\">I'm from</span><span class=\"plus\">+</span><span class=\"slot be\">страна</span><span class=\"plus\">=</span><span class=\"slot\">I'm</span><span class=\"plus\">+</span><span class=\"slot be\">национальность</span></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я из Италии. = Я итальянец.</span><span class=\"en\">I'm from <mark>Italy</mark>. = I'm <mark>Italian</mark>.</span></li>\n<li><span class=\"ru\">Она из Китая. Она китаянка.</span><span class=\"en\">She's from <mark>China</mark>. She's <mark>Chinese</mark>.</span></li>\n</ul>\n<p>Национальности образуются по нескольким образцам. Если знать образец, можно угадать и новые слова.</p>\n<div class=\"ng-grid\">\n<div class=\"ng\"><h4>-an / -ian</h4><ul><li>Italy → Italian</li><li>Germany → German</li><li>Brazil → Brazilian</li><li>Korea → Korean</li><li>Canada → Canadian</li><li>the USA → American</li></ul></div>\n<div class=\"ng\"><h4>-ish</h4><ul><li>Spain → Spanish</li><li>Poland → Polish</li><li>Turkey → Turkish</li><li>Ireland → Irish</li><li>the UK → British</li></ul></div>\n<div class=\"ng\"><h4>-ese</h4><ul><li>China → Chinese</li><li>Japan → Japanese</li><li>Vietnam → Vietnamese</li><li>Portugal → Portuguese</li></ul></div>\n<div class=\"ng\"><h4>особые</h4><ul><li>France → French</li><li>Greece → Greek</li><li>the Netherlands → Dutch</li><li>Switzerland → Swiss</li><li>Thailand → Thai</li></ul></div>\n</div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>После <b>from</b> — только страна: <span class=\"no\">I'm from Italian</span> <span class=\"yes\">I'm from Italy ✔</span></span></div>","groups":[{"title":"Напишите национальность","items":[{"t":"input","q":"Portugal →","a":["Portuguese"],"ex":"Группа -ese.","h":"Группа -ese: Portugal → Portug…ese."},{"t":"input","q":"Ireland →","a":["Irish"],"ex":"Группа -ish.","h":"Группа -ish, как Poland → Polish."},{"t":"input","q":"Korea →","a":["Korean"],"ex":"Группа -an.","h":"Группа -an: добавьте n."},{"t":"input","q":"Finland →","p":"Подсказка: как Poland → Polish","a":["Finnish"],"ex":"Finland → Finnish (две n).","h":"Как Poland → Polish: Fin + n + ish."},{"t":"input","q":"France →","a":["French"],"ex":"Особое слово.","h":"Особое слово, см. таблицу «особые»."},{"t":"input","q":"Switzerland →","a":["Swiss"],"ex":"Особое слово.","h":"Особое слово, см. таблицу «особые»."},{"t":"input","q":"Norway →","p":"Подсказка: -ian","a":["Norwegian"],"ex":"Norway → Norwegian.","h":"Norw + egian."},{"t":"input","q":"Argentina →","p":"Подсказка: -ian","a":["Argentinian","Argentine"],"ex":"Argentina → Argentinian.","h":"Argentin + ian."}]},{"title":"Выберите слово","items":[{"t":"choice","q":"Luca is from Rome. He's ___.","o":["Italian","Italy","Italish"],"a":"Italian","ex":"He's + национальность.","b":{"Italy":"Italy — страна. После He's нужна национальность.","Italish":"Такого слова нет. Italy относится к группе -ian."}},{"t":"choice","q":"Our new colleague is from Amsterdam. She's ___.","o":["Dutch","Netherlandish","Hollandian"],"a":"Dutch","ex":"the Netherlands → Dutch.","b":{"Netherlandish":"Такого слова нет. Это особое слово, см. таблицу.","Hollandian":"Такого слова нет. Это особое слово, см. таблицу."}},{"t":"choice","q":"I'm from ___.","o":["Brazil","Brazilian","Brazilish"],"a":"Brazil","ex":"После from — страна.","b":{"Brazilian":"После from — страна, а не национальность.","Brazilish":"Такого слова нет. И после from нужна страна."}},{"t":"choice","q":"Sushi is a ___ dish.","o":["Japanese","Japan","Japanish"],"a":"Japanese","ex":"«Японское блюдо» — национальность работает как прилагательное.","b":{"Japan":"Japan — страна. «Японское блюдо» — нужна национальность.","Japanish":"Такого слова нет. Japan относится к группе -ese."}},{"t":"choice","q":"Tacos are ___ food.","o":["Mexican","Mexico","Mexicanese"],"a":"Mexican","ex":"Mexico → Mexican.","b":{"Mexico":"Mexico — страна. «Мексиканская еда» — нужна национальность.","Mexicanese":"Такого слова нет. Mexico относится к группе -an."}}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"I'm from Spanish.","w":2,"c":"Spain","ex":"После from — страна: Spain."},{"t":"fix","q":"They are from Chinese.","w":3,"c":"China","ex":"После from — страна: China."},{"t":"fix","q":"My wife is France.","w":3,"c":"French","ex":"is + национальность: French."}]}]},{"id":"words","nav":"Фразы с доски","eyebrow":"Тема 7 · фразы со стикеров","title":"Фразы с ваших стикеров","theory":"<h3>above / below — над / под</h3>\n<p><b>above</b> — выше, над. <b>below</b> — ниже, под.</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">Картина висит над диваном.</span><span class=\"en\">The picture is <mark>above</mark> the sofa.</span></li>\n<li><span class=\"ru\">Твоя квартира под моей.</span><span class=\"en\">Your flat is <mark>below</mark> mine.</span></li>\n</ul>\n<h3>first of all — во-первых, прежде всего</h3>\n<ul class=\"examples\"><li><span class=\"ru\">Во-первых, спасибо, что пришли.</span><span class=\"en\"><mark>First of all</mark>, thank you for coming.</span></li></ul>\n<h3>15-minute meeting — число перед существительным</h3>\n<p>Если «сколько» стоит <b>перед</b> существительным и описывает его, пишем через дефис и <b>без -s</b>.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>Как описание</th><th>Перевод</th><th>Сравните</th></tr></thead>\n<tbody>\n<tr><td>a 15-<mark>minute</mark> meeting</td><td>15-минутная встреча</td><td>The meeting is 15 minute<mark>s</mark> long.</td></tr>\n<tr><td>a two-<mark>hour</mark> film</td><td>двухчасовой фильм</td><td>The film is two hour<mark>s</mark> long.</td></tr>\n<tr><td>a five-<mark>year</mark>-old boy</td><td>пятилетний мальчик</td><td>The boy is five year<mark>s</mark> old.</td></tr>\n</tbody></table></div>\n<h3>Погода</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Солнечно.</span><span class=\"en\"><mark>It is</mark> sunny.</span><span class=\"why\">It is + какая погода</span></li>\n<li><span class=\"ru\">Солнца нет.</span><span class=\"en\"><mark>There is no</mark> sun.</span><span class=\"why\">There is no + чего нет</span></li>\n<li><span class=\"ru\">Погода отличная.</span><span class=\"en\">The weather <mark>is</mark> perfect.</span></li>\n</ul>\n<h3>for — на какой срок</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">на день · на 6 месяцев</span><span class=\"en\"><mark>for</mark> a day · <mark>for</mark> 6 months</span></li>\n</ul>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>above · below · first of all · two-year · 15-minute meeting · It is sunny / There is no sun · for a day / for 6 months</span></div>","groups":[{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"We have a ___ break.","o":["10-minute","10-minutes","10 minute's"],"a":"10-minute","ex":"Перед существительным — без -s и через дефис.","b":{"10-minutes":"Перед существительным -s не ставим.","10 minute's":"Апостроф здесь не нужен. Нужен дефис и слово без -s."}},{"t":"choice","q":"It's a ___ course.","o":["three-month","three-months","three month"],"a":"three-month","ex":"a three-month course.","b":{"three-months":"Перед существительным -s не ставим.","three month":"Нужен дефис: three-month."}},{"t":"choice","q":"My daughter is a ___ girl.","o":["six-year-old","six-years-old","six years old"],"a":"six-year-old","ex":"a six-year-old girl. Но: She is six years old.","b":{"six-years-old":"Перед существительным -s не ставим.","six years old":"Так говорят в конце: She is six years old. Перед girl нужны дефисы и без -s."}},{"t":"choice","q":"My flat is on the 5th floor. Anna's flat is on the 4th floor. Her flat is ___ mine.","o":["below","above"],"a":"below","ex":"4-й этаж ниже 5-го → below.","b":{"above":"4-й этаж ниже 5-го. above — «выше»."}},{"t":"choice","q":"The clock is ___ the door, near the ceiling.","o":["above","below"],"a":"above","ex":"У потолка, то есть над дверью → above.","b":{"below":"Часы у потолка, то есть выше двери. below — «ниже»."}}]},{"title":"Выберите правильный перевод","items":[{"t":"choice","q":"«Во-первых, спасибо всем.»","o":["First of all, thank you all.","First all, thank you all.","At first of all, thanks all."],"a":"First of all, thank you all.","ex":"Устойчивая фраза first of all.","b":{"First all, thank you all.":"Пропущено of: first of all.","At first of all, thanks all.":"At здесь лишнее: first of all."}},{"t":"choice","q":"«Сегодня солнечно.»","o":["It is sunny today.","Is sunny today.","Today sunny."],"a":"It is sunny today.","ex":"It is + погода.","b":{"Is sunny today.":"Пропущено подлежащее it.","Today sunny.":"Нет ни подлежащего, ни глагола: It is sunny today."}},{"t":"choice","q":"«Солнца нет.»","o":["There is no sun.","It is no sun.","Is no sun."],"a":"There is no sun.","ex":"There is no + существительное.","b":{"It is no sun.":"«Чего-то нет» — это There is no + существительное.","Is no sun.":"Нужно There is no sun."}},{"t":"choice","q":"«Я уезжаю на 6 месяцев.»","o":["I'm going away for 6 months.","I'm going away on 6 months.","I'm going away during 6 month."],"a":"I'm going away for 6 months.","ex":"На какой срок → for.","b":{"I'm going away on 6 months.":"Срок — через for, а не on.","I'm going away during 6 month.":"Срок — через for. И после 6 нужно months с -s."}},{"t":"choice","q":"«Погода отличная.»","o":["The weather is perfect.","The weather perfect.","Is perfect weather."],"a":"The weather is perfect.","ex":"Нужен is.","b":{"The weather perfect.":"Пропущен глагол is.","Is perfect weather.":"Нужен порядок: The weather + is + perfect."}}]}]},{"id":"similar","nav":"its · interested","eyebrow":"Тема 8 · похожие слова","title":"its или it's, interesting или interested","theory":"<h3>it's или its</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Слово</th><th>Что значит</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>it's</td><td>= it is — «это есть, оно есть»</td><td><mark>It's</mark> a nice café.</td></tr>\n<tr><td>its</td><td>«его / её» про предмет или животное</td><td>The café is famous for <mark>its</mark> coffee.</td></tr>\n</tbody></table></div>\n<p><b>Проверка:</b> подставьте вместо слова <b>it is</b>. Если предложение по-прежнему имеет смысл, пишем <b>it's</b> с апострофом. Если получается ерунда, пишем <b>its</b>.</p>\n<ul class=\"examples\">\n<li><span class=\"ru\">Собака голодная. Её миска пустая.</span><span class=\"en\">The dog is hungry. <mark>Its</mark> bowl is empty.</span><span class=\"why\">«It is bowl is empty» — ерунда, значит its</span></li>\n<li><span class=\"ru\">Уже поздно.</span><span class=\"en\"><mark>It's</mark> late.</span><span class=\"why\">It is late — смысл есть, значит it's</span></li>\n</ul>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span><b>its name</b> — «его название». Без апострофа, потому что это не «it is».</span></div>\n<h3>interesting или interested</h3>\n<p>Окончание <b>-ing</b> описывает предмет: <b>какой он</b>, то есть что он вызывает. Окончание <b>-ed</b> описывает человека: <b>что он чувствует</b>.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>-ing: какой предмет</th><th>-ed: что чувствует человек</th></tr></thead>\n<tbody>\n<tr><td>The film is <mark>interesting</mark>. — Фильм интересный.</td><td>I'm <mark>interested</mark> in films. — Мне интересно кино.</td></tr>\n<tr><td>The lesson is <mark>boring</mark>. — Урок скучный.</td><td>I'm <mark>bored</mark>. — Мне скучно.</td></tr>\n<tr><td>The job is <mark>tiring</mark>. — Работа утомительная.</td><td>I'm <mark>tired</mark>. — Я устал.</td></tr>\n<tr><td>The trip is <mark>exciting</mark>. — Поездка захватывающая.</td><td>We're <mark>excited</mark>. — Мы в восторге.</td></tr>\n</tbody></table></div>\n<p>После <b>interested</b> всегда идёт <b>in</b>: I'm interested <b>in</b> music.</p>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span><span class=\"no\">I'm interesting in music</span> — получается «я интересный в музыке». <span class=\"yes\">I'm interested in music ✔</span></span></div>","groups":[{"title":"Выберите it's или its","items":[{"t":"choice","q":"___ raining again.","o":["It's","Its"],"a":"It's","ex":"It is raining — смысл есть, значит It's.","b":{"Its":"Проверка: It is raining. Смысл есть, значит нужен апостроф."}},{"t":"choice","q":"The company changed ___ name.","o":["it's","its"],"a":"its","ex":"«Своё название» у компании — its.","b":{"it's":"Проверка: «changed it is name» — ерунда. Значит its."}},{"t":"choice","q":"___ my birthday tomorrow.","o":["It's","Its"],"a":"It's","ex":"It is my birthday.","b":{"Its":"Проверка: It is my birthday. Смысл есть, значит нужен апостроф."}},{"t":"choice","q":"Look at that bird! ___ wings are blue.","o":["It's","Its"],"a":"Its","ex":"«Её крылья» — its wings.","b":{"It's":"Проверка: «It is wings are blue» — ерунда. Значит its."}},{"t":"choice","q":"I like this hotel. ___ near the beach.","o":["It's","Its"],"a":"It's","ex":"It is near the beach.","b":{"Its":"Проверка: It is near the beach. Смысл есть, значит нужен апостроф."}},{"t":"choice","q":"The cat is sleeping in ___ bed.","o":["it's","its"],"a":"its","ex":"«В своей кровати» — its bed.","b":{"it's":"Проверка: «in it is bed» — ерунда. Значит its."}}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"Its a good idea.","w":0,"c":"It's","ex":"It is a good idea → It's."},{"t":"fix","q":"The table is old, but it's legs are new.","w":5,"c":"its","ex":"«Её ножки» — its legs. «It is legs» не имеет смысла."}]},{"title":"Выберите -ing или -ed","items":[{"t":"choice","q":"This book is very ___.","o":["interesting","interested"],"a":"interesting","ex":"Книга — какая она → -ing.","b":{"interested":"-ed — про человека и его чувства. А здесь описываем книгу."}},{"t":"choice","q":"Are you ___ in football?","o":["interesting","interested"],"a":"interested","ex":"Человек и его интерес, плюс in → interested.","b":{"interesting":"Are you interesting? — «Ты интересный?». Спрашиваем про интерес человека, значит -ed."}},{"t":"choice","q":"I'm ___. Let's watch something else.","o":["bored","boring"],"a":"bored","ex":"Что я чувствую → bored.","b":{"boring":"I'm boring — «я скучный человек». Про чувство нужно -ed."}},{"t":"choice","q":"The lesson was ___, I almost fell asleep.","o":["bored","boring"],"a":"boring","ex":"Какой был урок → boring.","b":{"bored":"-ed — про человека. Урок — какой он, значит -ing."}},{"t":"choice","q":"After work I'm always ___.","o":["tired","tiring"],"a":"tired","ex":"Что я чувствую → tired.","b":{"tiring":"I'm tiring — «я утомительный». Про состояние нужно -ed."}},{"t":"choice","q":"We're really ___ about our trip!","o":["excited","exciting"],"a":"excited","ex":"Что мы чувствуем → excited.","b":{"exciting":"We're exciting — «мы захватывающие». Про чувство нужно -ed."}}]},{"title":"Переведите на английский","items":[{"t":"input","q":"«Мне интересна история.»","p":"история — history","a":["I'm interested in history."],"ex":"I'm interested in + чем."},{"t":"input","q":"«Этот фильм скучный.»","p":"этот фильм — this film","a":["This film is boring."],"ex":"Какой фильм → boring."}]}]},{"id":"rus","nav":"Перевод с русского","eyebrow":"Тема 9 · перевод","title":"Как не переводить слово в слово","theory":"<p>Многие ошибки появляются, когда переводим слово в слово. «Мне холодно», «Мне 25 лет», «Я согласен» по-английски строятся иначе. Эти фразы лучше запомнить целиком.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>По-русски</th><th>Дословно — ошибка</th><th>По-английски</th></tr></thead>\n<tbody>\n<tr><td>Мне холодно.</td><td><span class=\"no\">It is cold for me.</span></td><td><span class=\"yes\">I'm cold.</span></td></tr>\n<tr><td>Мне 25 лет.</td><td><span class=\"no\">I have 25 years.</span></td><td><span class=\"yes\">I'm 25.</span></td></tr>\n<tr><td>Я согласен.</td><td><span class=\"no\">I am agree.</span></td><td><span class=\"yes\">I agree.</span></td></tr>\n<tr><td>Я женат / замужем.</td><td><span class=\"no\">I have married.</span></td><td><span class=\"yes\">I'm married.</span></td></tr>\n<tr><td>Я боюсь пауков.</td><td><span class=\"no\">I afraid spiders.</span></td><td><span class=\"yes\">I'm afraid of spiders.</span></td></tr>\n<tr><td>Ты прав.</td><td><span class=\"no\">You have right.</span></td><td><span class=\"yes\">You're right.</span></td></tr>\n<tr><td>Мне скучно.</td><td><span class=\"no\">Me boring.</span></td><td><span class=\"yes\">I'm bored.</span></td></tr>\n</tbody></table></div>\n<p><b>Правило-проверка.</b> По-русски говорим «мне + состояние» (холодно, скучно, страшно). По-английски говорим «я есть + состояние»: I'm cold, I'm bored, I'm scared.</p>\n<p><b>agree</b> — это глагол-действие, как work. Поэтому <b>I agree</b>, без am. А «не согласен» — <b>I don't agree</b>.</p>\n<h3>Артикль a перед профессией</h3>\n<p>По-русски «Она врач». По-английски перед профессией в единственном числе ставим <b>a</b>, а перед гласным звуком <b>an</b>: She's <mark>a</mark> doctor. He's <mark>an</mark> engineer. Во множественном числе артикль не нужен: They're doctors.</p>","groups":[{"title":"Выберите правильный перевод","items":[{"t":"choice","q":"«Мне жарко.»","o":["I'm hot.","It is hot for me.","Me is hot."],"a":"I'm hot.","ex":"Своё состояние: I'm + hot.","b":{"It is hot for me.":"Дословный перевод. О своём состоянии говорим: I'm + состояние.","Me is hot.":"me не может быть подлежащим, нужно I."}},{"t":"choice","q":"«Моему сыну 7 лет.»","o":["My son is 7.","My son has 7 years.","My son 7 years."],"a":"My son is 7.","ex":"Возраст — через to be.","b":{"My son has 7 years.":"Дословный перевод. Возраст — через to be.","My son 7 years.":"Пропущен глагол is."}},{"t":"choice","q":"«Я не согласен.»","o":["I don't agree.","I'm not agree.","I not agree."],"a":"I don't agree.","ex":"agree — глагол-действие, to be с ним не нужен. Отрицание: I don't agree.","b":{"I'm not agree.":"agree — глагол-действие, am с ним не ставим. Отрицание: I don't agree.","I not agree.":"Одного not мало. Для глагола-действия: I don't agree."}},{"t":"choice","q":"«Мы боимся темноты.»","o":["We're afraid of the dark.","We afraid of the dark.","We have afraid of the dark."],"a":"We're afraid of the dark.","ex":"be afraid of — «бояться».","b":{"We afraid of the dark.":"afraid — не глагол, а состояние. Нужно are: We're afraid.","We have afraid of the dark.":"Не have, а to be: We're afraid."}},{"t":"choice","q":"«Он прав.»","o":["He's right.","He has right.","He right."],"a":"He's right.","ex":"be right — «быть правым».","b":{"He has right.":"Дословный перевод. «Быть правым» — be right.","He right.":"Пропущен глагол is."}},{"t":"choice","q":"«Мне страшно.»","o":["I'm scared.","It's scary for me.","Me scared."],"a":"I'm scared.","ex":"Что я чувствую → I'm scared.","b":{"It's scary for me.":"Дословный перевод. О своём чувстве: I'm scared.","Me scared.":"Нужно подлежащее I и глагол am."}}]},{"title":"Переведите на английский","items":[{"t":"input","q":"«Моя сестра — врач.»","p":"врач — doctor","a":["My sister is a doctor."],"ex":"Перед профессией — a."},{"t":"input","q":"«Мы не дома.»","p":"дома — at home","a":["We aren't at home.","We aren't home."],"ex":"We → aren't."},{"t":"input","q":"«Где твой телефон?»","p":"телефон — phone","a":["Where is your phone?"],"ex":"Where + is + your phone?"},{"t":"input","q":"«Ты занят?»","p":"занят — busy","a":["Are you busy?"],"ex":"Are + you + busy?"},{"t":"input","q":"«Откуда она?»","a":["Where is she from?"],"ex":"Where + is + she + from?"},{"t":"input","q":"«Сегодня тепло.»","p":"тепло — warm","a":["It is warm today.","Today it is warm."],"ex":"Подлежащее it обязательно."},{"t":"input","q":"«Мои родители не из Москвы.»","p":"родители — parents","a":["My parents aren't from Moscow."],"ex":"Parents → aren't."},{"t":"input","q":"«Сколько лет твоему брату?»","p":"брат — brother","a":["How old is your brother?"],"ex":"How old + is + your brother?"},{"t":"input","q":"«Он инженер.»","p":"инженер — engineer","a":["He is an engineer."],"ex":"engineer начинается с гласного звука → an."}]}]},{"id":"past","nav":"-ing и was / were","hard":true,"eyebrow":"Тема 10 · тоже с доски","title":"am / is / are + -ing и was / were","theory":"<p>Этот блок сложнее остальных. На доске он есть в упражнениях («I ___ learning English at this moment», «The presentations ___ well-received yesterday»), поэтому разбираем и его.</p>\n<h3>am / is / are + глагол-ing — «прямо сейчас»</h3>\n<p>Когда действие идёт в этот момент, to be соединяется с глаголом + <b>-ing</b>.</p>\n<div class=\"formula\"><span class=\"slot\">кто</span><span class=\"plus\">+</span><span class=\"slot be\">am · is · are</span><span class=\"plus\">+</span><span class=\"slot be\">глагол-ing</span></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Я читаю (сейчас).</span><span class=\"en\">I <mark>am reading</mark>.</span></li>\n<li><span class=\"ru\">Идёт дождь.</span><span class=\"en\">It <mark>is raining</mark>.</span></li>\n<li><span class=\"ru\">Они не слушают.</span><span class=\"en\">They <mark>aren't listening</mark>.</span></li>\n<li><span class=\"ru\">Ты сейчас работаешь?</span><span class=\"en\"><mark>Are</mark> you <mark>working</mark> now?</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Не путайте</span><span><span class=\"no\">I am work</span> — ошибка. <span class=\"yes\">I am working ✔</span> — «работаю сейчас». <span class=\"yes\">I work ✔</span> — «работаю вообще».</span><span>Слова-подсказки: now, right now, at the moment, currently.</span></div>\n<h3>was / were — to be в прошлом</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Кто</th><th>+</th><th>−</th><th>?</th></tr></thead>\n<tbody>\n<tr><td>I / he / she / it</td><td><mark>was</mark></td><td>wasn't</td><td>Was it good?</td></tr>\n<tr><td>we / you / they</td><td><mark>were</mark></td><td>weren't</td><td>Were they late?</td></tr>\n</tbody></table></div>\n<p>Слова-подсказки: yesterday, last week, two days ago, in 2020.</p>\n<p>В деловом английском часто встречается <b>was / were + 3-я форма глагола</b> — «был сделан»: The meeting <mark>was scheduled</mark> last week. — Встреча была назначена на прошлой неделе.</p>","groups":[{"title":"Прямо сейчас: выберите форму","items":[{"t":"choice","q":"Look! It ___ snowing.","o":["is","are","am"],"a":"is","ex":"It → is snowing."},{"t":"choice","q":"We ___ waiting for the bus right now.","o":["is","are","am"],"a":"are","ex":"We → are waiting."},{"t":"choice","q":"I ___ cooking dinner at the moment.","o":["is","are","am"],"a":"am","ex":"I → am cooking."},{"t":"choice","q":"The kids ___ sleeping, they're playing.","o":["aren't","isn't","not"],"a":"aren't","ex":"Kids → they → aren't.","b":{"not":"Одного not мало: нужен глагол to be + not."}},{"t":"choice","q":"___ you listening to me?","o":["Are","Is","Do"],"a":"Are","ex":"Вопрос: Are + you + listening.","b":{"Is":"Is — для одного (he / she / it). С you нужно are.","Do":"С -ing (listening) вопрос строится через am / is / are."}}]},{"title":"Прошлое: was или were","items":[{"t":"choice","q":"I ___ ill yesterday.","o":["was","were"],"a":"was","ex":"I → was."},{"t":"choice","q":"The tickets ___ very expensive last year.","o":["was","were"],"a":"were","ex":"Tickets — несколько → were."},{"t":"choice","q":"___ you at the party on Saturday?","o":["Was","Were"],"a":"Were","ex":"You → were."},{"t":"choice","q":"The hotel ___ clean, so we left.","o":["wasn't","weren't"],"a":"wasn't","ex":"Hotel = it → wasn't."},{"t":"choice","q":"My parents ___ at home last night.","o":["was","were"],"a":"were","ex":"Parents → they → were."}]},{"title":"Деловые предложения: am, is, are, was или were","items":[{"t":"choice","q":"Our company ___ currently looking for a new designer.","o":["is","are","was"],"a":"is","ex":"Currently — сейчас; company = it → is.","b":{"are":"Company — одна компания, то есть it.","was":"currently значит «сейчас», а was — прошлое."}},{"t":"choice","q":"The report ___ ready yesterday.","o":["is","was","were"],"a":"was","ex":"Yesterday → прошлое; report = it → was.","b":{"is":"yesterday — это прошлое.","were":"Report — один, значит was."}},{"t":"choice","q":"___ the clients happy with the presentation last week?","o":["Was","Were","Are"],"a":"Were","ex":"Last week → прошлое; clients → were.","b":{"Was":"Clients — несколько, значит were.","Are":"last week — это прошлое."}},{"t":"choice","q":"I ___ responsible for social media in our team.","o":["am","is","was"],"a":"am","ex":"Сейчас, I → am.","b":{"is":"С I нельзя is, только am.","was":"Речь о том, что сейчас, а was — прошлое."}},{"t":"choice","q":"The new prices ___ announced two days ago.","o":["was","were","are"],"a":"were","ex":"Two days ago → прошлое; prices → were announced.","b":{"was":"Prices — несколько, значит were.","are":"two days ago — это прошлое."}},{"t":"choice","q":"We ___ working on this project at the moment, it's on hold.","o":["aren't","isn't","weren't"],"a":"aren't","ex":"At the moment → сейчас; we → aren't.","b":{"isn't":"We — это несколько, значит aren't.","weren't":"at the moment значит «сейчас», а weren't — прошлое."}}]}]},{"id":"intro","nav":"Знакомство","eyebrow":"Тема 11 · о себе","title":"Знакомство: Nice to meet you","theory":"<p>Как представиться и рассказать о себе — из урока «People and places» (упражнение «представьтесь на конференции») и из профиля «Friendly Face».</p>\n<h3>Представиться</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Привет, я Лена.</span><span class=\"en\">Hi, <mark>I'm</mark> Lena. / <mark>My name's</mark> Lena.</span><span class=\"why\">My name's = My name is</span></li>\n<li><span class=\"ru\">Как тебя зовут?</span><span class=\"en\"><mark>What's your name?</mark></span></li>\n<li><span class=\"ru\">Приятно познакомиться.</span><span class=\"en\"><mark>Nice to meet you.</mark></span><span class=\"why\">ответ: Nice to meet you, too.</span></li>\n<li><span class=\"ru\">Это Мелани.</span><span class=\"en\"><mark>This is</mark> Melanie.</span><span class=\"why\">так знакомят с кем-то</span></li>\n<li><span class=\"ru\">Какая у тебя фамилия?</span><span class=\"en\">What's your <mark>surname</mark>? / your <mark>second name</mark>?</span></li>\n</ul>\n<h3>to meet и to get acquainted</h3>\n<p>«Знакомиться» в разговоре — <b>to meet</b>: Nice to meet you, We met at work. <b>to get acquainted</b> — книжное «познакомиться поближе», в речи звучит редко.</p>\n<h3>Откуда вы и кто по национальности</h3>\n<div class=\"compare\"><div><span class=\"en\">I'm from Russia.</span><span class=\"ru\">Я из России.</span><span class=\"small\">from + страна</span></div><div><span class=\"en\">I'm Russian.</span><span class=\"ru\">Я русский / россиянин.</span><span class=\"small\">национальность, с большой буквы</span></div></div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>После from — только страна: <span class=\"no\">I'm from Russian.</span> <span class=\"yes\">I'm from Russia. ✔</span></span><span>Национальность — с большой буквы и без from: <span class=\"no\">I'm russian.</span> <span class=\"yes\">I'm Russian. ✔</span></span></div>\n<h3>Хобби, чувства, любимое</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Слово</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td><mark>hobbies</mark> — хобби, увлечения</td><td>My hobbies are tennis and reading.</td></tr>\n<tr><td><mark>feelings</mark> — чувства: happy, tired, bored, sad</td><td>How are you feeling today? — I'm a bit tired.</td></tr>\n<tr><td><mark>favourite</mark> — любимый</td><td>My favourite month is May.</td></tr>\n</tbody></table></div>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>«У меня не так много хобби»: <span class=\"no\">I have not so many hobbies.</span> <span class=\"yes\">I don't have many hobbies. ✔</span></span><span>«У меня много событий»: <span class=\"yes\">I have a lot of events. ✔</span> — правильно, а в значении «много дел» чаще говорят <span class=\"yes\">I'm very busy. ✔</span></span></div>\n<h3>Ваши вопросы с доски</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">В каком ты классе / группе?</span><span class=\"en\"><mark>What class are you in?</mark></span><span class=\"why\">предлог in — в конце</span></li>\n<li><span class=\"ru\">Почему ты в этом классе?</span><span class=\"en\"><mark>Why are you in this class?</mark></span></li>\n<li><span class=\"ru\">Какой твой любимый месяц?</span><span class=\"en\"><mark>What's your favourite month?</mark></span></li>\n<li><span class=\"ru\">Тебе интересна фотография?</span><span class=\"en\"><mark>Are you interested in photography?</mark></span><span class=\"why\">photography — фотография (занятие), photographer — фотограф</span></li>\n</ul>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>to get acquainted / to meet · = I am Russian · I have not so many hobbies · I have a lot of events / feelings · What class are you in? · Why are you in this class? · What is your second name? · What's your favorite month?</span></div>","groups":[{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"A: Hi, I'm Nick. B: Hi, Nick. ___","o":["Nice to meet you.","Nice to meeting you.","Nice meet you."],"a":"Nice to meet you.","ex":"Устойчивая фраза: Nice to meet you."},{"t":"choice","q":"___ is my friend Anna.","o":["This","He","It's"],"a":"This","ex":"Знакомим с кем-то: This is…"},{"t":"choice","q":"«Я россиянка.»","o":["I'm Russian.","I'm from Russian.","I'm Russia."],"a":"I'm Russian.","ex":"Национальность без from.","b":{"I'm from Russian.":"После from — страна: I'm from Russia.","I'm Russia.":"Russia — страна. Национальность — Russian."}},{"t":"choice","q":"«Я из России.»","o":["I'm from Russia.","I'm from Russian.","I from Russia."],"a":"I'm from Russia.","ex":"from + страна, и не забываем am."},{"t":"choice","q":"«У меня не так много хобби.»","o":["I don't have many hobbies.","I have not so many hobbies.","I am not many hobbies."],"a":"I don't have many hobbies.","ex":"don't have many."},{"t":"choice","q":"«Мой любимый цвет — синий.»","o":["My favourite colour is blue.","My loved colour is blue.","My favourite colour blue."],"a":"My favourite colour is blue.","ex":"favourite — любимый, и нужен is."},{"t":"choice","q":"What class ___ you in?","o":["are","do","is"],"a":"are","ex":"you → are, предлог in в конце."},{"t":"choice","q":"I'm interested in ___. I love taking pictures.","o":["photography","photographer","photo"],"a":"photography","ex":"Занятие — photography."}]},{"title":"Переведите на английский","items":[{"t":"input","q":"«Как тебя зовут?»","a":["What's your name?","What is your name?"],"ex":"What + is + your name?","p":"Переведите на английский"},{"t":"input","q":"«Приятно познакомиться.»","a":["Nice to meet you.","Nice to meet you too."],"ex":"Nice to meet you.","p":"Переведите на английский"},{"t":"input","q":"«Я русский.»","a":["I'm Russian.","I am Russian."],"ex":"I'm + Russian (с большой буквы).","p":"Переведите на английский"},{"t":"input","q":"«Почему ты в этом классе?»","a":["Why are you in this class?"],"ex":"Why + are + you + in this class?","p":"Переведите на английский"}]},{"title":"Соберите вопрос","items":[{"t":"order","w":["are","in","what","class","you"],"a":["What class are you in?"],"ex":"What class + are + you + in?"},{"t":"order","w":["what","favourite","your","is","month"],"a":["What is your favourite month?"],"ex":"What + is + your favourite month?"},{"t":"order","w":["you","are","interested","photography","in"],"a":["Are you interested in photography?"],"ex":"Are + you + interested in + photography?"}]}]},{"id":"words2","nav":"Фразы с доски 2","eyebrow":"Тема 12 · ещё фразы со стикеров","title":"Фразы с ваших стикеров, часть 2","theory":"<h3>Где находится: above, below, in the middle…</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Фраза</th><th>Значение</th></tr></thead>\n<tbody>\n<tr><td>above / below</td><td>над / под</td></tr>\n<tr><td>in the middle / in the centre</td><td>посередине / в центре</td></tr>\n<tr><td>on the left / on the right</td><td>слева / справа</td></tr>\n</tbody></table></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Анна на фото в центре.</span><span class=\"en\">Anna is <mark>in the middle</mark> of the photo.</span></li>\n<li><span class=\"ru\">Мой дом справа.</span><span class=\"en\">My house is <mark>on the right</mark>.</span></li>\n</ul>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span>С left и right нужны on the: <span class=\"no\">My house is right.</span> <span class=\"yes\">My house is on the right. ✔</span></span></div>\n<h3>time — «время» и «раз»</h3>\n<div class=\"tbl\"><table>\n<thead><tr><th>Значение</th><th>Как сказать</th><th>Пример</th></tr></thead>\n<tbody>\n<tr><td>время (нельзя посчитать)</td><td>time — без a и без -s</td><td>I haven't got <mark>time</mark>.</td></tr>\n<tr><td>раз (можно посчитать)</td><td>a time · times</td><td>It isn't our first <mark>time</mark> here. · three <mark>times</mark> a week</td></tr>\n</tbody></table></div>\n<h3>hundred — сто</h3>\n<p><b>a hundred / one hundred</b> — сто. После числа <b>без -s</b>: two <b>hundred</b>, five hundred. Между сотнями и десятками — <b>and</b>: 125 = one hundred <b>and</b> twenty-five.</p>\n<div class=\"pit\"><span class=\"tag\">Частая ошибка</span><span><span class=\"no\">two hundreds</span> <span class=\"yes\">two hundred ✔</span></span></div>\n<h3>Первый день, второй курс</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">У него сегодня первый день здесь.</span><span class=\"en\"><mark>It is his first day</mark> here.</span></li>\n<li><span class=\"ru\">Она студентка второго курса.</span><span class=\"en\">She's a <mark>second-year student</mark>.</span><span class=\"why\">как two-year, 15-minute: через дефис, без -s</span></li>\n<li><span class=\"ru\">Всё, на этом всё.</span><span class=\"en\"><mark>That's it.</mark></span><span class=\"why\">That is it — вот и всё / именно так</span></li>\n</ul>\n<h3>present / absent, ill / sick</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Все присутствуют?</span><span class=\"en\">Is everybody <mark>present</mark>?</span><span class=\"why\">to be present — присутствовать</span></li>\n<li><span class=\"ru\">Мои коллеги отсутствуют на работе.</span><span class=\"en\">My colleagues <mark>are absent</mark> from work.</span><span class=\"why\">to be absent from</span></li>\n<li><span class=\"ru\">Я болею сегодня.</span><span class=\"en\">I'm <mark>ill</mark> today. / I'm <mark>sick</mark> today.</span><span class=\"why\">ill — брит., sick — амер., смысл один</span></li>\n<li><span class=\"ru\">Меня тошнит.</span><span class=\"en\">I feel <mark>sick</mark>.</span><span class=\"why\">в британском feel sick — именно «тошнит»</span></li>\n</ul>\n<h3>to be going to — собираться</h3>\n<div class=\"formula\"><span class=\"slot\">кто</span><span class=\"plus\">+</span><span class=\"slot be\">am · is · are going to</span><span class=\"plus\">+</span><span class=\"slot\">глагол</span></div>\n<ul class=\"examples\">\n<li><span class=\"ru\">Мы собираемся прочитать статью.</span><span class=\"en\">We <mark>are going to</mark> read the article.</span></li>\n<li><span class=\"ru\">Я собираюсь позвонить маме.</span><span class=\"en\">I<mark>'m going to</mark> call my mum.</span></li>\n</ul>\n<h3>Ещё фразы</h3>\n<ul class=\"examples\">\n<li><span class=\"ru\">Надеюсь, всё получится.</span><span class=\"en\">I hope it will <mark>work out</mark>.</span><span class=\"why\">work out — получиться, наладиться (а ещё — тренироваться)</span></li>\n<li><span class=\"ru\">Моя ошибка! / Виноват.</span><span class=\"en\"><mark>My bad!</mark></span><span class=\"why\">разговорное</span></li>\n<li><span class=\"ru\">Нам нужно принять решение.</span><span class=\"en\">We need to <mark>make a decision</mark>.</span><span class=\"why\">take a decision — тоже верно, чаще в британском</span></li>\n<li><span class=\"ru\">брови · ресницы</span><span class=\"en\"><mark>eyebrows</mark> · <mark>eyelashes</mark></span></li>\n<li><span class=\"ru\">Я тебе не вру.</span><span class=\"en\">I don't <mark>lie</mark> to you.</span></li>\n</ul>\n<h3>Слова на -tion</h3>\n<p>Окончание <b>-tion</b> читается «шн», ударение — на слог перед ним: ambi<b>TION</b> → am<b>BI</b>tion.</p>\n<div class=\"tbl\"><table>\n<thead><tr><th>Слово</th><th>Перевод</th></tr></thead>\n<tbody>\n<tr><td>ambition</td><td>амбиция, стремление</td></tr>\n<tr><td>condition</td><td>условие, состояние</td></tr>\n<tr><td>competition</td><td>соревнование, конкуренция</td></tr>\n<tr><td>exception</td><td>исключение</td></tr>\n</tbody></table></div>\n<div class=\"sticky\"><span class=\"tag\">С вашей доски</span><span>above / below / in the center / in the middle / left / right · that's it · It is his first day here · second year student · to work out / I hope it will work out · time — время / раз · hundred · eyebrows / eyelashes · WE are going to · to be present / to be absent · to be ill / to be sick · We need to take a decision · My bad · ambition / condition / competition / exception</span></div>","groups":[{"title":"Выберите правильный вариант","items":[{"t":"choice","q":"The picture is ___ the sofa.","o":["above","on the right","in the middle"],"a":"above","ex":"над диваном → above."},{"t":"choice","q":"The bank is ___, next to the café.","o":["on the left","left","in left"],"a":"on the left","ex":"on the left — слева."},{"t":"choice","q":"«У меня нет времени.»","o":["I haven't got time.","I haven't got a time.","I haven't got times."],"a":"I haven't got time.","ex":"Время — без a и -s."},{"t":"choice","q":"I go to the gym three ___ a week.","o":["time","times","hours"],"a":"times","ex":"раз → times."},{"t":"choice","q":"300 — three ___","o":["hundred","hundreds","hundred of"],"a":"hundred","ex":"После числа — hundred без -s."},{"t":"choice","q":"She's a ___ student.","o":["second-year","second-years","second year's"],"a":"second-year","ex":"Через дефис, без -s."},{"t":"choice","q":"My partner is ___ from work today.","o":["absent","present","ill"],"a":"absent","ex":"absent from work — отсутствует на работе."},{"t":"choice","q":"We ___ going to visit my parents.","o":["are","do","—"],"a":"are","ex":"be going to: we are going to."},{"t":"choice","q":"Don't worry, I'm sure it will ___.","o":["work out","work up","go out"],"a":"work out","ex":"work out — получится."},{"t":"choice","q":"«Нам нужно принять решение.»","o":["We need to make a decision.","We need to do a decision.","We need to accept a decision."],"a":"We need to make a decision.","ex":"make (или take) a decision."},{"t":"choice","q":"«брови» — ___","o":["eyebrows","eyelashes","eyes"],"a":"eyebrows","ex":"eyebrows — брови, eyelashes — ресницы."},{"t":"choice","q":"«исключение» — ___","o":["exception","condition","ambition"],"a":"exception","ex":"exception — исключение."}]},{"title":"Напишите","items":[{"t":"input","q":"125 →","a":["one hundred and twenty-five","a hundred and twenty-five","one hundred and twenty five","a hundred and twenty five"],"ex":"hundred + and + twenty-five.","p":"Напишите число словами","h":"one hundred and…"},{"t":"input","q":"I / going to / call my mum","a":["I'm going to call my mum.","I am going to call my mum."],"ex":"I + am + going to + call…","p":"Составьте предложение"}]},{"title":"Нажмите на неправильное слово","items":[{"t":"fix","q":"My house is right.","w":3,"c":"on the right","ex":"Слева / справа — on the left / on the right."},{"t":"fix","q":"Five hundreds people came.","w":1,"c":"hundred","ex":"После числа — hundred."},{"t":"fix","q":"We is going to read the article.","w":1,"c":"are","ex":"we → are going to."}]}]},{"id":"final","nav":"Итоговый тест","eyebrow":"Итоговый тест · все темы вперемешку","title":"Проверьте себя","theory":"<p>Все темы вперемешку. Если ошибётесь, вернитесь к объяснению нужной темы через меню сверху.</p>","groups":[{"title":"Смешанные задания","items":[{"t":"choice","q":"My grandparents ___ from Armenia.","o":["am","is","are"],"a":"are","ex":"Тема 1: grandparents → they → are."},{"t":"input","q":"The lesson is difficult.","p":"Сделайте отрицание","a":["The lesson isn't difficult."],"ex":"Тема 2: is → isn't."},{"t":"order","w":["is","where","nearest","the","pharmacy"],"a":["Where is the nearest pharmacy?"],"ex":"Тема 4: Where + is + the nearest pharmacy?"},{"t":"choice","q":"Is your dad a pilot? — No, ___.","o":["he isn't","he's not a","he doesn't"],"a":"he isn't","ex":"Тема 3: Is he…? → No, he isn't.","b":{"he's not a":"Короткий ответ заканчивается на глаголе: No, he isn't.","he doesn't":"Вопрос задан с is, значит и ответ с to be."}},{"t":"input","q":"Sweden →","p":"Напишите национальность (как Poland → Polish)","a":["Swedish"],"ex":"Тема 6: Sweden → Swedish.","h":"Swed + ish."},{"t":"choice","q":"I ___ agree with you.","o":["—","am","is"],"a":"—","ex":"Тема 5: есть глагол agree, am не нужен."},{"t":"choice","q":"___ old is your car?","o":["How","What","When"],"a":"How","ex":"Тема 4: How old — сколько лет.","b":{"What":"«Сколько лет» — это How old.","When":"«Сколько лет» — это How old."}},{"t":"fix","q":"They is very friendly.","w":1,"c":"are","ex":"Тема 1: they → are."},{"t":"choice","q":"It was a ___ flight.","o":["three-hour","three-hours","three hour's"],"a":"three-hour","ex":"Тема 7: без -s и через дефис.","b":{"three-hours":"Перед существительным -s не ставим.","three hour's":"Апостроф не нужен: three-hour."}},{"t":"choice","q":"It ___ windy yesterday.","o":["was","is","were"],"a":"was","ex":"Тема 8: yesterday, it → was."},{"t":"input","q":"Mark is at the gym.","p":"Спросите: где?","a":["Where is Mark?"],"ex":"Тема 4: Where + is + Mark?"},{"t":"choice","q":"Sorry, I can't talk now. I ___ driving.","o":["am","is","—"],"a":"am","ex":"Тема 8: I am driving — прямо сейчас.","b":{"is":"С I нельзя is, только am.","—":"Форма -ing без am не бывает: I am driving."}},{"t":"input","q":"The museum is open today.","p":"Превратите в вопрос","a":["Is the museum open today?"],"ex":"Тема 3: Is + the museum + open today?"},{"t":"order","w":["are","you","from","where"],"a":["Where are you from?"],"ex":"Тема 4: from — в конец."}]}]}]}$lesson$::jsonb)
