-- Lesson 7: Контрольные работы (7 sections, 178 items)
insert into public.lessons (slug, title, subtitle, position, content)
values ('tests', 'Контрольные работы', 'по контрольной на каждый урок и большая итоговая по всему курсу', 7, $lesson${"steps":false,"sections":[{"id":"t1","nav":"К1 · to be","eyebrow":"Контрольная 1 · урок 1","title":"Глагол to be","theory":"<p>Проверка по уроку <b>1 «Глагол to be»</b>. Новые задания, которых не было в уроке.</p>\n<p><b>Что проверяем:</b> am / is / are · отрицания · вопросы и короткие ответы · where / what / how · порядок слов · страны · its / it's · -ing / -ed · перевод · was / were</p>\n<p>Решайте без подсказок и не открывайте объяснения. Итог внизу страницы покажет, сколько решено с первой попытки. Ошибки попадут в «Мои ошибки», их можно перерешать.</p>","groups":[{"title":"Часть A · выберите","items":[{"t":"choice","q":"My cousins ___ from Brazil.","o":["am","is","are"],"a":"are","ex":"cousins = they → are."},{"t":"choice","q":"The weather ___ terrible today.","o":["am","is","are"],"a":"is","ex":"weather = it → is."},{"t":"choice","q":"I ___ not ready yet.","o":["am","is","are"],"a":"am","ex":"I → am."},{"t":"choice","q":"___ your office far from here?","o":["Am","Is","Are"],"a":"Is","ex":"office = it → Is."},{"t":"choice","q":"Are you and Kate sisters? — Yes, ___.","o":["we are","we're","they are"],"a":"we are","ex":"you and Kate → we. Короткое «да» без сокращения."},{"t":"choice","q":"Is the museum open on Mondays? — No, ___.","o":["it isn't","it not","isn't"],"a":"it isn't","ex":"No, it isn't."},{"t":"choice","q":"___ is your birthday? — In May.","o":["Where","When","Who"],"a":"When","ex":"In May — когда → When."},{"t":"choice","q":"___ are you from? — I'm from Kazan.","o":["What","Where","How"],"a":"Where","ex":"Откуда → Where … from."},{"t":"choice","q":"He's from Sweden. He's ___.","o":["Swedish","Swedian","Swede's"],"a":"Swedish","ex":"Sweden → Swedish."},{"t":"choice","q":"The hotel is famous for ___ view.","o":["it's","its"],"a":"its","ex":"Чей вид? Отеля → its."},{"t":"choice","q":"I'm ___ in art.","o":["interesting","interested"],"a":"interested","ex":"Мне интересно → I'm interested."},{"t":"choice","q":"«Мне скучно.»","o":["I'm bored.","I'm boring.","Me is boring."],"a":"I'm bored.","ex":"Состояние человека → bored."},{"t":"choice","q":"I ___ at home yesterday.","o":["am","was","were"],"a":"was","ex":"yesterday → прошлое, I → was."},{"t":"choice","q":"Look! The children ___ playing in the snow.","o":["is","are","—"],"a":"are","ex":"Прямо сейчас: are + playing."}]},{"title":"Часть B · напишите","items":[{"t":"input","q":"They are at the office.","a":["They aren't at the office.","They are not at the office.","They're not at the office."],"ex":"are → aren't.","p":"Сделайте отрицание"},{"t":"input","q":"Your brother is married.","a":["Is your brother married?"],"ex":"Is + your brother + married?","p":"Превратите в вопрос"},{"t":"input","q":"«Мне 30 лет.»","a":["I'm 30.","I am 30.","I'm 30 years old.","I am 30 years old.","I'm thirty.","I am thirty."],"ex":"Возраст — через to be.","p":"Переведите на английский"},{"t":"input","q":"«Где твои ключи?»","a":["Where are your keys?"],"ex":"keys → are.","p":"Переведите на английский"}]},{"title":"Часть C · найдите ошибку и соберите","items":[{"t":"fix","q":"My parents is on holiday.","w":2,"c":"are","ex":"parents = they → are."},{"t":"fix","q":"I amn't hungry.","w":1,"c":"am not","ex":"Формы amn't нет: I'm not / I am not."},{"t":"order","w":["film","what","your","is","favourite"],"a":["What is your favourite film?"],"ex":"What + is + your favourite film?"},{"t":"order","w":["it","very","is","cold","today"],"a":["It is very cold today."],"ex":"It + is + very cold + today."}]},{"title":"Часть D · знакомство и фразы с доски (темы 11–12)","items":[{"t":"choice","q":"A: This is my brother, Tom. B: ___","o":["Nice to meet you.","Nice meeting to you.","I meet you."],"a":"Nice to meet you.","ex":"Nice to meet you."},{"t":"choice","q":"«Я из России, я русский.»","o":["I'm from Russia. I'm Russian.","I'm from Russian. I'm Russia.","I from Russia. I Russian."],"a":"I'm from Russia. I'm Russian.","ex":"from + страна; национальность — Russian."},{"t":"choice","q":"The chemist's is ___, next to the bank.","o":["on the right","right","at right"],"a":"on the right","ex":"on the right."},{"t":"choice","q":"I go swimming two ___ a week.","o":["time","times","timing"],"a":"times","ex":"раз → times."},{"t":"choice","q":"Five ___ people work in our company.","o":["hundred","hundreds","hundred of"],"a":"hundred","ex":"После числа — hundred."},{"t":"input","q":"«Нам нужно принять решение.»","a":["We need to make a decision.","We need to take a decision."],"ex":"make / take a decision.","p":"Переведите на английский"}]}]},{"id":"t2","nav":"К2 · whose","eyebrow":"Контрольная 2 · урок 2","title":"Чьё это? Вещи и принадлежность","theory":"<p>Проверка по уроку <b>2 «Чьё это?»</b>. Новые задания, которых не было в уроке.</p>\n<p><b>Что проверяем:</b> вещи · this / these / that / those · my / your… · mine / yours… · whose · 's · inside / outside, pleasant</p>\n<p>Решайте без подсказок и не открывайте объяснения. Итог внизу страницы покажет, сколько решено с первой попытки. Ошибки попадут в «Мои ошибки», их можно перерешать.</p>","groups":[{"title":"Часть A · выберите","items":[{"t":"choice","q":"«солнцезащитные очки» — ___","o":["sunglasses","sunglass","sun glass"],"a":"sunglasses","ex":"Всегда во множественном: sunglasses."},{"t":"choice","q":"«кошелёк для денег» — ___","o":["wallet","charger","scarf"],"a":"wallet","ex":"wallet — кошелёк."},{"t":"choice","q":"My earrings ___ in the bathroom.","o":["is","are"],"a":"are","ex":"earrings — несколько → are."},{"t":"choice","q":"___ are my new shoes. Do you like them? (они у вас на ногах)","o":["This","These","Those"],"a":"These","ex":"Близко и несколько → These."},{"t":"choice","q":"Who is ___ woman over there?","o":["this","that","those"],"a":"that","ex":"Далеко, одна → that."},{"t":"choice","q":"Ben can't find ___ phone.","o":["his","her","him"],"a":"his","ex":"Ben → his."},{"t":"choice","q":"The cat is eating. ___ food is in the kitchen.","o":["It's","Its","Her"],"a":"Its","ex":"Кошка → its."},{"t":"choice","q":"That laptop isn't ___. It's my brother's.","o":["my","mine","me"],"a":"mine","ex":"Без предмета → mine."},{"t":"choice","q":"Is this scarf ___, Anna?","o":["your","yours","you"],"a":"yours","ex":"Без предмета → yours."},{"t":"choice","q":"___ car is this? — It's Mike's.","o":["Who","Who's","Whose"],"a":"Whose","ex":"Чья? → Whose."},{"t":"choice","q":"This is my ___ room. (у меня две сестры, комната общая)","o":["sister's","sisters'","sisters's"],"a":"sisters'","ex":"Две сёстры: sisters + ' → sisters'."},{"t":"choice","q":"It's raining. Let's stay ___.","o":["outside","inside"],"a":"inside","ex":"Дождь → останемся внутри."},{"t":"choice","q":"These gloves aren't ours. They're ___. (Tom and Lisa)","o":["their","theirs","them"],"a":"theirs","ex":"they → theirs."}]},{"title":"Часть B · напишите","items":[{"t":"input","q":"This is Kate's notebook. → This notebook is ___.","a":["hers"],"ex":"Kate → she → hers.","p":"Впишите одно слово","h":"she → h…"},{"t":"input","q":"That is my key.","a":["Those are my keys."],"ex":"that → those, is → are, key → keys.","p":"Напишите про несколько предметов"},{"t":"input","q":"(these / sunglasses)","a":["Whose sunglasses are these?","Whose are these sunglasses?"],"ex":"Whose + sunglasses + are + these?","p":"Спросите, чьи это вещи"},{"t":"input","q":"Are these your gloves?","a":["Are these yours?","Are they yours?"],"ex":"your gloves → yours.","p":"Замените с помощью mine, yours, hers…"}]},{"title":"Часть C · найдите ошибку и соберите","items":[{"t":"fix","q":"Who's bag is this?","w":0,"c":"Whose","ex":"Чья? → Whose."},{"t":"fix","q":"This are my keys.","w":0,"c":"These","ex":"keys — несколько → These are."},{"t":"fix","q":"Is this pen your?","w":3,"c":"yours","ex":"Без предмета → yours."},{"t":"order","w":["is","whose","on","the","table","wallet"],"a":["Whose wallet is on the table?"],"ex":"Whose wallet + is + on the tab